const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
let out
try {
  const root = parseDocument(readFileSync(0, 'utf8'))
  if (args[0] === 'json') out = toJson(root, 0) + '\n'
  else {
    const lines = []
    toKeys(root, '', lines)
    out = lines.map((l) => l + '\n').join('')
  }
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
process.stdout.write(out)
